<?php
declare(strict_types=1);
require_once __DIR__.'/../config/config.php';
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/includes/auth.php';
$db=db();$pkStmt=$db->query("SHOW KEYS FROM projects WHERE Key_name='PRIMARY'");$pkRow=$pkStmt?$pkStmt->fetch():false;$pk=$pkRow['Column_name']??'id';if(!preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/',$pk))$pk='id';
$id=(int)($_POST['project_id']??$_GET['id']??0);$stmt=$db->prepare("SELECT * FROM projects WHERE `{$pk}`=? LIMIT 1");$stmt->execute([$id]);$project=$stmt->fetch();if(!$project){http_response_code(404);exit('Project not found.');}$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$gallery=json_decode((string)($project['gallery']??''),true);$gallery=is_array($gallery)?array_values(array_filter($gallery,'is_string')):[];$root=realpath(__DIR__.'/..');$projectDir=realpath($root.'/uploads/projects/'.$id);
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'');if($action==='delete_gallery'){$index=(int)($_POST['index']??-1);if(isset($gallery[$index])){$path=$gallery[$index];$absolute=realpath($root.'/'.ltrim($path,'/\\'));if($absolute&&$projectDir&&str_starts_with($absolute,$projectDir.DIRECTORY_SEPARATOR)&&is_file($absolute))@unlink($absolute);array_splice($gallery,$index,1);$db->prepare("UPDATE projects SET gallery=? WHERE `{$pk}`=?")->execute([json_encode($gallery,JSON_UNESCAPED_SLASHES),$id]);}$msg='Gallery image deleted.';}elseif($action==='move_gallery'){$from=(int)($_POST['from']??-1);$to=(int)($_POST['to']??-1);if(isset($gallery[$from],$gallery[$to])){$item=$gallery[$from];array_splice($gallery,$from,1);array_splice($gallery,$to,0,[$item]);$db->prepare("UPDATE projects SET gallery=? WHERE `{$pk}`=?")->execute([json_encode($gallery,JSON_UNESCAPED_SLASHES),$id]);}$msg='Gallery order updated.';}elseif($action==='delete_hero'){$hero=(string)($project['featured_image']??'');$absolute=realpath($root.'/'.ltrim($hero,'/\\'));if($absolute&&$projectDir&&str_starts_with($absolute,$projectDir.DIRECTORY_SEPARATOR)&&is_file($absolute))@unlink($absolute);$db->prepare("UPDATE projects SET featured_image=NULL WHERE `{$pk}`=?")->execute([$id]);$msg='Hero image deleted.';}elseif($action==='set_hero_from_gallery'){$index=(int)($_POST['index']??-1);if(isset($gallery[$index])){$hero=$gallery[$index];$db->prepare("UPDATE projects SET featured_image=? WHERE `{$pk}`=?")->execute([$hero,$id]);$msg='Hero image updated.';}}$stmt=$db->prepare("SELECT * FROM projects WHERE `{$pk}`=? LIMIT 1");$stmt->execute([$id]);$project=$stmt->fetch();$gallery=json_decode((string)($project['gallery']??''),true);$gallery=is_array($gallery)?array_values(array_filter($gallery,'is_string')):[];}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Media | <?=$esc($project['title'])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>.thumb{height:180px;width:100%;object-fit:cover;border-radius:14px}.drag{cursor:grab}.hero{height:300px;width:100%;object-fit:cover;border-radius:18px}</style></head><body class="bg-light"><main class="container py-5" style="max-width:1100px"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">Media Manager</h1><p class="text-muted mb-0"><?=$esc($project['title'])?></p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="project-form.php?id=<?=$id?>">Edit Project</a><a class="btn btn-dark" href="projects.php">Projects</a></div></div><?php if(!empty($msg)):?><div class="alert alert-success"><?=$esc($msg)?></div><?php endif;?><section class="card border-0 shadow-sm p-4 mb-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">Hero Image</h2><?php if(!empty($project['featured_image'])):?><form method="post" onsubmit="return confirm('Delete the hero image?')"><input type="hidden" name="project_id" value="<?=$id?>"><input type="hidden" name="action" value="delete_hero"><button class="btn btn-sm btn-outline-danger">Delete Hero</button></form><?php endif;?></div><?php if(!empty($project['featured_image'])):?><img class="hero" src="<?=$esc(app_url($project['featured_image']))?>" alt="Hero image"><?php else:?><div class="border rounded-4 p-5 text-center text-muted">No hero image uploaded.</div><?php endif;?></section><section class="card border-0 shadow-sm p-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h5 mb-1">Gallery</h2><p class="small text-muted mb-0">Drag images to reorder. Changes are saved immediately.</p></div><span class="badge text-bg-dark"><?=count($gallery)?> images</span></div><div class="row g-4" id="gallery"><?php foreach($gallery as $i=>$image):?><div class="col-md-4 drag-item" draggable="true" data-index="<?=$i?>"><div class="card h-100 border-0 shadow-sm"><img class="thumb" src="<?=$esc(app_url($image))?>" alt="Gallery image <?=$i+1?>" loading="lazy"><div class="card-body"><div class="small text-muted mb-2">Image <?=$i+1?></div><div class="d-flex gap-2 flex-wrap"><form method="post"><input type="hidden" name="project_id" value="<?=$id?>"><input type="hidden" name="action" value="set_hero_from_gallery"><input type="hidden" name="index" value="<?=$i?>"><button class="btn btn-sm btn-outline-primary">Set as Hero</button></form><form method="post" onsubmit="return confirm('Delete this gallery image?')"><input type="hidden" name="project_id" value="<?=$id?>"><input type="hidden" name="action" value="delete_gallery"><input type="hidden" name="index" value="<?=$i?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></div></div></div><?php endforeach;?></div><?php if(!$gallery):?><div class="text-center text-muted py-5">No gallery images yet. Add images from the project editor.</div><?php endif;?></section></main><script>const gallery=document.getElementById('gallery');let dragged=null;if(gallery){gallery.querySelectorAll('.drag-item').forEach(el=>{el.addEventListener('dragstart',()=>{dragged=el});el.addEventListener('dragover',e=>{e.preventDefault();const target=e.currentTarget;if(dragged&&dragged!==target){const items=[...gallery.querySelectorAll('.drag-item')];const a=items.indexOf(dragged),b=items.indexOf(target);if(a<b)gallery.insertBefore(dragged,target.nextSibling);else gallery.insertBefore(dragged,target);}});el.addEventListener('dragend',async()=>{if(!dragged)return;const items=[...gallery.querySelectorAll('.drag-item')];const old=Number(dragged.dataset.index);const fresh=items.indexOf(dragged);if(old!==fresh){const fd=new FormData();fd.append('project_id','<?=$id?>');fd.append('action','move_gallery');fd.append('from',old);fd.append('to',fresh);await fetch(location.href,{method:'POST',body:fd});location.reload();}dragged=null});});}</script></body></html>